<template>
  <div ref="viewport" class="leader-viewport" :class="{ 'is-fullscreen': fullscreen }">
    <main class="leader-wall" :style="canvasStyle" aria-label="学工中心领导大屏">
      <header class="lw-header">
        <div class="lw-brand"><span>YK</span><div><b>{{ snapshot.brand }}</b><small>学生事务 · 治理与服务</small></div></div>
        <div class="lw-title"><h1>学工中心运行总览</h1><p>看见重点 · 跟进办理 · 守护成长</p></div>
        <div class="lw-actions"><button :disabled="loading" @click="$emit('refresh')">{{ loading ? '更新中' : '刷新' }}</button><button @click="showContracts = true">指标口径</button><button @click="toggleFullscreen">{{ fullscreen ? '退出全屏' : '全屏' }}</button><time>{{ clock }}</time></div>
      </header>

      <section class="lw-brief" :class="brief.tone"><span>领导关注</span><div><h2>{{ brief.title }}</h2><p>{{ brief.note }}</p></div><em>数据范围 <b>{{ snapshot.scope }}</b></em></section>

      <section class="lw-kpis" aria-label="核心指标">
        <button v-for="item in kpis" :key="item.id" :class="['lw-kpi', item.tone, metricState(item.id)]" @click="openMetric(item.id)"><span>{{ item.label }}</span><strong>{{ value(item.id) }}<small>{{ metric(item.id)?.status === 'OK' ? metric(item.id)?.unit : '' }}</small></strong><em>{{ item.note }}</em></button>
      </section>

      <section class="lw-upper">
        <article class="lw-panel lw-backlog"><PanelTitle title="学工办理积压" subtitle="审核、公示等当前在办记录" /><div class="lw-bars"><button v-for="row in backlog" :key="row.id" @click="openMetric(row.id)"><span>{{ row.label }}</span><i><b :style="{ width: barWidth(row.id, backlog) }" /></i><strong>{{ value(row.id) }}</strong></button></div><p class="lw-note">各项沿用所属业务状态，不合并成“全校待办”。</p></article>
        <article class="lw-panel lw-risk"><PanelTitle title="风险处置全景" subtitle="当前存量记录 · 人数与记录数分开" /><div class="lw-risk-body"><button class="lw-risk-ring" :style="riskRing" @click="openMetric('riskOpen')"><span>未关闭风险记录</span><strong>{{ value('riskOpen') }}</strong><small>条 · 待继续处置</small></button><div class="lw-risk-grid"><button v-for="row in riskStats" :key="row.id" @click="openMetric(row.id)"><span>{{ row.label }}</span><strong :class="row.tone">{{ value(row.id) }}</strong><small>条</small></button></div></div><p class="lw-note">存量构成，不作为本月绩效或总体安全结论。</p></article>
        <article class="lw-panel lw-priority"><PanelTitle title="重点跟进事项" subtitle="只展示聚合数量" /><ol><li v-for="(row,index) in priorities" :key="row.id"><button @click="openMetric(row.id)"><i>{{ index + 1 }}</i><span><b>{{ row.label }}</b><small>{{ row.note }}</small></span><strong>{{ value(row.id) }}</strong></button></li></ol><p class="lw-note">不展示学生身份、心理事由及其他敏感内容。</p></article>
      </section>

      <section class="lw-lower">
        <article class="lw-panel"><PanelTitle title="住宿资源" subtitle="床位台账" /><div class="lw-dorm"><strong>{{ value('occupancy', 1) }}<small>{{ metric('occupancy')?.status === 'OK' ? '%' : '' }}</small></strong><span>总床位 <b>{{ value('beds') }}</b></span></div><div class="lw-segment"><i :style="{ width: segment('occupied') }" /><i :style="{ width: segment('vacant') }" /><i :style="{ width: segment('locked') }" /></div><dl class="lw-three"><div><dt>已入住</dt><dd>{{ value('occupied') }}</dd></div><div><dt>空床</dt><dd>{{ value('vacant') }}</dd></div><div><dt>锁定</dt><dd>{{ value('locked') }}</dd></div></dl></article>
        <article class="lw-panel"><PanelTitle title="困难认定与奖助" subtitle="按申请记录统计" /><div class="lw-aid"><button @click="openMetric('aidApproved')"><span>已认定申请</span><strong>{{ value('aidApproved') }}</strong><small>/ {{ value('aidTotal') }} 件</small></button><button @click="openMetric('fundingGranted')"><span>已获资助申请</span><strong>{{ value('fundingGranted') }}</strong><small>/ {{ value('fundingTotal') }} 件</small></button></div><p class="lw-note">获批不代表资金已经到账。</p></article>
        <article class="lw-panel"><PanelTitle title="成长活动与沟通" subtitle="不同业务分别计数" /><div class="lw-growth"><button @click="openMetric('activities')"><strong>{{ value('activities') }}</strong><span>场活动</span></button><button @click="openMetric('creditStudents')"><strong>{{ value('creditStudents') }}</strong><span>人获二课学分</span></button></div><div class="lw-communication"><span>谈心记录 <b>{{ value('talkCompleted') }}</b></span><span>家校联系 <b>{{ value('family') }}</b></span></div></article>
        <article class="lw-panel"><PanelTitle title="归档与隐私保护" subtitle="敏感业务最小展示" /><button class="lw-archive" @click="openMetric('archivePending')"><span>尚未归档档案包</span><strong>{{ value('archivePending') }}</strong><small>/ {{ value('archiveTotal') }} 份</small></button><div class="lw-privacy"><b>心理关注 · 专项授权范围</b><span>无授权不等于零风险；大屏不展示个人明细。</span></div></article>
      </section>

      <footer class="lw-footer"><span><i />数据更新 {{ updatedLabel }}</span><span>当前存量统计 · 无跨期比较</span><span>F 全屏 · Esc 退出</span></footer>
    </main>

    <div v-if="detail" class="lw-modal" role="dialog" aria-modal="true" aria-labelledby="leader-metric-title" @click.self="detail = null"><article><button class="lw-close" aria-label="关闭" @click="detail = null">×</button><span>指标口径</span><h2 id="leader-metric-title">{{ detail.label }}</h2><strong>{{ value(detail.id, detail.unit === '%' ? 1 : 0) }} {{ detail.status === 'OK' ? detail.unit : '' }}</strong><p>{{ detail.note }}</p><dl><div><dt>当前状态</dt><dd>{{ statusText(detail.status) }}</dd></div><div><dt>数据范围</dt><dd>{{ snapshot.scope }}</dd></div></dl><button v-if="canDrill(detail.id)" class="lw-primary" @click="go(detail)">查看业务明细</button></article></div>
    <div v-if="showContracts" class="lw-modal" role="dialog" aria-modal="true" aria-labelledby="leader-contract-title" @click.self="showContracts = false"><article><button class="lw-close" aria-label="关闭" @click="showContracts = false">×</button><span>阅读说明</span><h2 id="leader-contract-title">领导大屏指标口径</h2><p>首行结论只根据本次成功返回的聚合值生成。缺权限、无范围、字段缺失和接口异常不会被解释成零，也不会生成“总体正常”一类结论。</p><p>风险学生人数与风险记录数分别展示；床位入住率来自床位台账；奖助获批不表示资金到账。</p></article></div>
  </div>
</template>

<script setup>
import { computed, defineComponent, h, onBeforeUnmount, onMounted, ref } from 'vue'
import { canCode } from '@/modules/studentAffairs/composables/permission'
import { formatWallMetric } from '@/modules/studentAffairs/composables/studentAffairsWallProjection'
import { WALL_ROUTES, WALL_STATUS_TEXT } from '@/modules/studentAffairs/config/studentAffairsWall.contract'

const props = defineProps({ snapshot: { type: Object, required: true }, ctx: { type: Object, default: null }, loading: Boolean })
const emit = defineEmits(['refresh', 'drill'])
const PanelTitle = defineComponent({ props: { title: String, subtitle: String }, setup: p => () => h('header', { class: 'lw-panel-title' }, [h('h3', p.title), h('span', p.subtitle)]) })
const viewport = ref(null), scale = ref(1), fullscreen = ref(false), detail = ref(null), showContracts = ref(false), clock = ref('')
let observer, clockTimer
const kpis = [{ id: 'students', label: '学生主档数', tone: '' , note: '当前授权范围' }, { id: 'classes', label: '班级数', tone: '', note: '不含已删除班级' }, { id: 'riskStudents', label: '未结风险学生', tone: 'amber', note: '按学生去重' }, { id: 'pendingLeave', label: '待审请假', tone: 'blue', note: '当前审核节点' }, { id: 'overdueLeave', label: '逾期未销假', tone: 'red', note: '非实时未归' }, { id: 'occupied', label: '已入住床位', tone: 'teal', note: '床位台账' }]
const backlog = [{ id: 'pendingAid', label: '困难认定在办' }, { id: 'pendingFunding', label: '奖助评审在办' }, { id: 'pendingDiscipline', label: '处分审理在办' }, { id: 'workPending', label: '勤工申请待审' }, { id: 'familyPending', label: '家校联系待回执' }]
const riskStats = [{ id: 'riskTotal', label: '风险记录总量', tone: '' }, { id: 'riskClosed', label: '已关闭记录', tone: 'teal' }, { id: 'riskLate', label: '处置超时', tone: 'red' }, { id: 'riskUnassigned', label: '未分派责任人', tone: 'amber' }]
const priorities = [{ id: 'riskLate', label: '风险处置超时', note: '核查处置进展与责任人' }, { id: 'overdueLeave', label: '逾期未销假', note: '跟进返校与销假确认' }, { id: 'familyPending', label: '家校联系待回执', note: '跟进家长反馈' }, { id: 'archivePending', label: '档案包待归档', note: '核对业务办结材料' }]
const canvasStyle = computed(() => ({ transform: `translate(-50%, -50%) scale(${scale.value})` }))
const updatedLabel = computed(() => { const raw = props.snapshot.sourceTimes?.cockpit || props.snapshot.sourceTimes?.dashboard; if (!raw) return '尚未取得'; const d = new Date(raw); return Number.isNaN(d.getTime()) ? '时间待确认' : d.toLocaleString('zh-CN', { hour12: false }) })
const riskRing = computed(() => { const m = metric('riskRate'); const n = m?.status === 'OK' ? Math.max(0, Math.min(100, m.value)) : 0; return { background: `radial-gradient(circle at center,#132b3d 0 58%,transparent 59%),conic-gradient(#67d7c3 ${n}%,#edba77 ${n}% 100%)` } })
const brief = computed(() => {
  const usable = priorities.map(item => ({ ...item, metric: metric(item.id) })).filter(item => item.metric?.status === 'OK' && item.metric.value > 0)
  if (!usable.length) return { tone: 'quiet', title: '当前重点需结合各业务可用数据核查', note: '部分指标可能为零、受限或暂不可用，未据此生成总体结论。' }
  const sorted = usable.sort((a, b) => b.metric.value - a.metric.value).slice(0, 3)
  return { tone: sorted.some(item => ['riskLate', 'overdueLeave'].includes(item.id)) ? 'attention' : 'normal', title: `优先跟进${sorted.map(item => item.label).join('、')}`, note: sorted.map(item => `${item.label} ${formatWallMetric(item.metric)} ${item.metric.unit}`).join(' · ') }
})
function metric(id) { return props.snapshot.metrics?.[id] }
function value(id, digits = 0) { return formatWallMetric(metric(id), digits) }
function metricState(id) { return 'state-' + String(metric(id)?.status || 'MISSING').toLowerCase() }
function statusText(status) { return WALL_STATUS_TEXT[status] || '暂不可用' }
function barWidth(id, rows) { const values = rows.map(row => metric(row.id)).filter(m => m?.status === 'OK').map(m => m.value); const max = Math.max(...values, 1); const m = metric(id); return `${m?.status === 'OK' ? Math.max(3, m.value / max * 100) : 0}%` }
function segment(id) { const total = metric('beds'), part = metric(id); return total?.status === 'OK' && total.value > 0 && part?.status === 'OK' ? `${Math.max(0, Math.min(100, part.value / total.value * 100))}%` : '0%' }
function routeKey(id) { return metric(id)?.route }
function canDrill(id) { const route = WALL_ROUTES[routeKey(id)]; return Boolean(route && canCode(props.ctx, route.permission) && metric(id)?.status === 'OK') }
function openMetric(id) { detail.value = metric(id) || null }
function go(item) { if (canDrill(item.id)) emit('drill', item.route) }
function resize() { if (!viewport.value) return; const box = viewport.value.getBoundingClientRect(); scale.value = Math.min(box.width / 1920, box.height / 1080) }
async function toggleFullscreen() { try { if (document.fullscreenElement === viewport.value) await document.exitFullscreen(); else await viewport.value?.requestFullscreen() } catch { /* 保留等比画幅 */ } }
function onFullscreen() { fullscreen.value = document.fullscreenElement === viewport.value; resize() }
function onKey(event) { if (event.key === 'Escape') { detail.value = null; showContracts.value = false } else if (event.key.toLowerCase() === 'f' && !event.ctrlKey && !event.metaKey && !event.altKey) toggleFullscreen() }
function tick() { clock.value = new Date().toLocaleTimeString('zh-CN', { hour12: false }) }
onMounted(() => { observer = new ResizeObserver(resize); observer.observe(viewport.value); document.addEventListener('fullscreenchange', onFullscreen); window.addEventListener('keydown', onKey); tick(); clockTimer = window.setInterval(tick, 1000); resize() })
onBeforeUnmount(() => { observer?.disconnect(); document.removeEventListener('fullscreenchange', onFullscreen); window.removeEventListener('keydown', onKey); window.clearInterval(clockTimer) })
</script>

<style scoped>
